def _review(
    route: str,
    target: str,
    candidate_source: str,
    candidate_needle: str,
    reason_code: str,
    followup: str,
    input_difference: str,
    output_difference: str,
    side_effect_difference: str,
) -> dict[str, Any]:
    return {
        "target": target,
        "reason_code": reason_code,
        "followup": followup,
        "candidate_source": candidate_source,
        "candidate_needle": candidate_needle,
        "contract_mismatch": {
            "input": f"{route}: {input_difference}",
            "output": f"{route}: {output_difference}",
            "side_effects": f"{route}: {side_effect_difference}",
        },
    }


